INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cc5a1ca3-5d3a-46e8-83fb-aa3041161533', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$41. óra: Összetett műveletek, zárójelfelbontás$q$, $q$Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "aa48a167-a67d-4add-a882-6cb7c71e966a", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "564b23ad-dbe1-4da0-a78e-02012ae0518e", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "8ce4eec9-6490-4f24-8830-237da3918a6d", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "ab1ccd52-1d5e-49f3-bf7d-6d2fbeb0ff80", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "322ef15a-79f2-4afc-b78f-101b3ac6580b", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "2a65de4b-e5f6-4596-96f0-97b39e7d308f", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "6e0263b8-0a91-4bde-8bf2-83b58c8b7d2e", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "095bb658-400b-4af0-9927-81bae51a19a1", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "c9ef5335-d2eb-40f2-bfda-12552b18d639", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "cd066c52-c50b-49a8-b5fb-b1ce04809c74", "text": "Igaz", "isCorrect": true}, {"id": "f598d7bc-1987-4640-8b4d-6754e4d48a7e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04f8c95e-ea9a-45e0-9c38-cb4332140372", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "1be31b6c-f876-4fae-b52f-c1d1da535817", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('81d81f7b-e696-4aa1-9be5-e238a1785b26', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$42. óra: Összetett műveletek, zárójelfelbontás gyakorlása$q$, $q$Gyakorlás feladatlapok és összetett kifejezések segítségével.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "d370b200-a526-4b65-b44d-2c03e4d8416a", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "8a81a6dc-8668-4bdb-89c4-ac2940be0c1a", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "4aaed808-eedd-475c-9320-65198ea16d44", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "ecadc9f0-5a65-4150-a427-b233988c1137", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "f0f86186-c197-492f-8ed3-fee84988df7c", "text": "Igaz", "isCorrect": true}, {"id": "ed7297c0-74f6-44fa-bf36-048299742363", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec95d662-3c7a-4901-8597-5e2690d091ce", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "c691ed09-019a-4a32-b73b-d76404020bc0", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "0793afb4-66b5-4165-a4d3-8d8ac579f890", "text": "Igaz", "isCorrect": true}, {"id": "6b076fd3-e2b0-4c41-88f0-2163d9de8133", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d2997090-3d35-41af-aeb7-845859f8963c", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cb5417cf-ae76-4ce9-8c38-534b5badfb58', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$43. óra: Összefoglalás$q$, $q$A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "8bc75cfe-edb7-4eb2-b9cb-7356aa09ab12", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "9149716f-2164-4b8a-b5a4-7e999cad6946", "text": "3/5", "isCorrect": true}, {"id": "86df763c-45ee-4ea2-8977-ae91d09ca94a", "text": "12/20", "isCorrect": false}, {"id": "37a15012-75c6-4475-bfdb-4206373299d8", "text": "7/9", "isCorrect": false}, {"id": "f86d20e7-904b-43ff-836a-d448757266e1", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "87cc21d8-9abe-4a56-bed3-e9fd1a4a2d3b", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "ec2c4aaf-4123-41c4-ae93-f3bb6e6c5427", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "c5fea4b8-eba1-4677-969a-673e5f91e415", "text": "1/6", "isCorrect": false}, {"id": "74a3f64c-8dbc-4ace-9a67-8545a72e1350", "text": "2/3", "isCorrect": false}, {"id": "7b106fea-797b-4ee5-9bbb-cf4148728154", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "65a6e122-48d6-4740-96de-5b43e1ee9fd5", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "2e2a243b-23c4-49b9-8e72-65aa49b44335", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "616ae8fa-3a59-4993-b14a-9166efd953e4", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "ac8676ed-13a9-4974-8495-fdf71cd35e06", "text": "Igaz", "isCorrect": true}, {"id": "dbb92c95-756e-4149-aefd-e19f00e2f643", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76e20493-1de8-41db-9925-74ee8d4d23e9", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "4a98e36d-10a2-426c-ab23-ba89db1ac09b", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('55b1885e-cf3f-4e9c-9df9-52ae491c8257', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$44. óra: Feladatmegoldás$q$, $q$Gyakorló feladatok megbeszélése egyéni és csoportmunkában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "d8ccc947-db2d-4d9a-aaeb-575edd0ebabc", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "9b7a232c-cc64-4279-b882-2d79d4ed699e", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "6c45f845-a7f8-4f86-a560-d178becbf1f9", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "f2c9b7ab-e7a3-4d6c-9382-b60378893159", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "ec66b33d-ce31-4e87-a04a-b325e9e000b4", "text": "1/5", "isCorrect": false}, {"id": "6e3f3ce5-811a-4df0-9cfc-2be416dbf447", "text": "1/2", "isCorrect": false}, {"id": "53209a1f-75f1-4a0a-add3-c029da72ab5c", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "a8458924-fd2d-48c4-9133-0500115276b5", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "82fdd7d5-7cf6-499b-8404-55e47483dc3c", "text": "Igaz", "isCorrect": true}, {"id": "5fc5d4bc-3b0e-4446-9265-53bd3db59413", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c4c63a7b-5867-4390-bc89-b24be3be1c99", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "a7001830-67e2-4488-b20c-c22a08a55113", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "59e1325c-4e52-4dfb-ab51-d351411738a2", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "1df67511-637d-4105-9ae5-6d79b8d8ab9c", "text": "Igaz", "isCorrect": true}, {"id": "728e8338-7b37-494f-9563-01429fffe247", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0cd58b4-214c-433b-8ef2-a1f1e58f8a36', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$45. óra: Játékos feladatok törtekkel$q$, $q$Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "67da23aa-ed34-4a3c-871c-6953e7aceb24", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "6a6e6737-2fe2-49dc-a2d9-27f1318e09fc", "text": "1/3", "isCorrect": true}, {"id": "e5cd5d94-9d6d-45f2-bedc-211a2648dda9", "text": "1/4", "isCorrect": false}, {"id": "49400d60-38a8-45df-b75a-bc6c4a935757", "text": "2/3", "isCorrect": false}, {"id": "99108c38-ebad-4f21-b9fa-7ca518021c08", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "37059bc8-3570-44c7-af8c-0a7e1425f6a0", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "ed3665e5-9573-4df6-9936-1ab1f6e71f0b", "text": "1/4", "isCorrect": true}, {"id": "34ff47d5-1aaf-467f-b708-54f43a9ab00d", "text": "1/5", "isCorrect": false}, {"id": "2e2bd7bb-9a0c-444b-b3b5-e027dcabffc9", "text": "2/5", "isCorrect": false}, {"id": "e800143c-362a-4a0b-9eda-4b517821183a", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "69d1f92e-b668-4f79-b893-9ddf8bcad9e8", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "bd0762a7-0697-461f-a210-8f1f08aa4001", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "8b8c5df2-c63b-4e3e-bd4a-0efaf7317f9b", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "f3249886-8e1c-4ce5-bc38-9d39db36769c", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "d8384b4d-38c2-43de-a70a-1036ca4a811f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a4eb6af3-ab15-4f9f-a314-5929c471a9f3", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "2b30fa98-18f9-4ee8-ac85-a0ad607b2e68", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "448c45e9-7df4-44ab-bcc7-f998aedf125b", "text": "Igaz", "isCorrect": true}, {"id": "b2437dbb-c083-4f2d-ad16-8e6f292ea9cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5fa10bd8-066d-4ba8-8bd6-7054dd777a98', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$46. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés a Törtek fejezetből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "bbe65f50-0f89-442a-9ad1-e7a1059dbc15", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "bd0d54f5-7c9e-4bbe-803f-bcd85b941697", "text": "5/6", "isCorrect": true}, {"id": "a0c2b1fe-a5bd-400c-9ee1-14c95cee54c9", "text": "3/9", "isCorrect": false}, {"id": "540e829d-522d-4fc1-af65-d0a20b1adb0d", "text": "3/6", "isCorrect": false}, {"id": "62a2c8f2-1e90-4f1f-8460-53b3adfdb136", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "dc5bb02e-dee8-4c41-9370-29083f14226a", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "494581cc-97f8-446f-b368-ac5f52929168", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "79712f28-b792-4df5-8bb3-14d095bd4641", "text": "8/11", "isCorrect": false}, {"id": "a1408e5f-cc52-479d-9f5c-ee5150a522b5", "text": "15/11", "isCorrect": false}, {"id": "89583fe9-3895-4d84-947e-9ffd28b66b24", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "4d8190fe-a3e9-4024-a9e7-05c3781c3863", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "f00567cc-d85f-4a64-a4b5-fe093819ffb7", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "16fa40bd-4608-4b2f-9dc9-b84dd30b8646", "text": "3/8", "isCorrect": false}, {"id": "cc63fddc-a2a1-42da-9304-31468653be7c", "text": "1/4", "isCorrect": false}, {"id": "abc61502-978d-412b-a25f-ad36ceecc51b", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "9e955249-9497-447c-97cf-e7cbbe59c160", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "16d18136-039b-4127-8838-9f71fe2033e2", "text": "9/4", "isCorrect": true}, {"id": "87f45bcf-b808-4378-a9f9-9d6c1d5b7d88", "text": "-4/9", "isCorrect": false}, {"id": "b1b10f43-8786-4b7c-8e21-8653138b6546", "text": "1/4", "isCorrect": false}, {"id": "096b54f6-3eb3-48cd-8eb2-d5a5e55d7f89", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "df03a7d1-a8ae-434e-a768-6f2b3cd6726f", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "9845b43e-85ac-479e-ae6e-d61d6cae8f95", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "98b612a7-7ded-4ed9-bd02-366028b17676", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "695b73b8-2b26-425e-9410-4c89ee816500", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "240f6c13-8a01-4297-868c-39946a987807", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "ee14afd1-116c-46f7-b30c-3bf01c4e3b44", "text": "Igaz", "isCorrect": true}, {"id": "8942bb44-0b90-459c-b2ce-d27470e4ef9b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4a7139fa-f1d9-4fc3-bee6-274eed405fd6", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('50a01a73-e2b0-4a25-9a52-eb75461d66ea', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$47. óra: Témazáró dolgozat értékelése$q$, $q$A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "fcd21c29-69e9-4b2d-8e7c-ef6cc9708c1f", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "98066008-cd55-4099-8254-f17c328d069d", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "b2280f77-dc00-4cc3-8853-f6c91e69d1b8", "text": "A számlálók leírása", "isCorrect": false}, {"id": "f7eeb980-a309-4d9a-858a-0cf05ff7b917", "text": "A zárójel használata", "isCorrect": false}, {"id": "0c129bcf-73b4-496d-afdd-6b3f7e6bffb2", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "f02f49ce-25f7-4b57-a7f1-5e016efc8d8e", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "b3b84985-0873-4cf0-899e-8321732c8189", "text": "Igaz", "isCorrect": true}, {"id": "38829219-8ec2-4aa4-81e2-2e49deeafa8d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46f6579f-1d99-44ad-90f3-d470d572b5bf", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "2d720ca9-94f7-4805-8693-db8148adb76d", "text": "2/5", "isCorrect": true}, {"id": "21efe9d0-c1cc-4a24-a8fb-1ed49eb6363c", "text": "4/10", "isCorrect": false}, {"id": "c9edce87-c51b-46ca-a2a5-59ae3c7a6673", "text": "1/5", "isCorrect": false}, {"id": "2b1e06c7-852e-4804-bb07-a9cb6de3f5af", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "e3dbc99c-8a98-4da2-98d1-97cd74532b2c", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "8406a4e0-703c-49c5-806a-8ed39be2e38d", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "1ada97c9-b9bc-48f6-910b-51261d655427", "text": "Igaz", "isCorrect": true}, {"id": "2f748e0c-2f9c-4bed-b853-56680f2e5502", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1f3c5ac4-9bbc-4e9d-90b9-6c11bf543b0c", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9db3c534-1ea1-48d7-a4ba-19254e531b95", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b0aa0b4e-bf8e-40db-9079-6e41cb5a08d1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$48. óra: Síkbeli alakzatok$q$, $q$Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "922cb8c5-035c-4cd1-9fb8-157acbb37e0e", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "2bc3ab9c-83ee-4027-ac14-b1e86d467edf", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "63c6cb95-71a8-4d2b-b199-7cb51fdfea88", "text": "Hegyesszög", "isCorrect": true}, {"id": "34c2783c-f267-4c40-9c77-90e453493e8f", "text": "Derékszög", "isCorrect": false}, {"id": "271a0e04-757c-4f37-87a7-5881e884c1ba", "text": "Tompaszög", "isCorrect": false}, {"id": "4f439d40-9602-4d76-87ec-69a0f038195f", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "c3a27836-bca3-419b-b9e3-252053409019", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "0656b703-09fd-479f-ae92-c3f97a59733d", "text": "Derékszög", "isCorrect": true}, {"id": "3f6ac7dc-da30-49d4-bdf8-41c773a4c80b", "text": "Hegyesszög", "isCorrect": false}, {"id": "4f1d589f-343c-4691-9d5e-8ae83d11fba5", "text": "Tompaszög", "isCorrect": false}, {"id": "9e5c8c10-547c-42b1-81f4-e7d893d8fd53", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "4749bb94-e69d-4f42-92d9-6a0e3b8917c4", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "e02cbdc2-d735-4f93-905d-ce2313866039", "text": "Tompaszög", "isCorrect": true}, {"id": "7e897aa7-5f32-40d6-911b-618afd5d9755", "text": "Hegyesszög", "isCorrect": false}, {"id": "6838a775-4063-4bd4-b0f3-d378e2ad0698", "text": "Derékszög", "isCorrect": false}, {"id": "13fea07c-a7fb-4bc5-994c-35807a7b00ee", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "98389c66-4b02-4369-9609-513456847725", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "23d5070b-9678-46e7-bf98-ccb9c67ae94e", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "0bdc85f6-19d3-42fa-ab44-b7c6fc1f75ad", "text": "Igaz", "isCorrect": true}, {"id": "6a832b6f-d490-4a39-a06a-21581b130794", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c4940d64-98b2-4f53-98c7-bfc14fdc0c08", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "d6e29efa-ed41-44bc-82aa-c87b8389e8b8", "text": "Igaz", "isCorrect": true}, {"id": "3161857c-6e71-469d-9f5a-b0b2b6497ba9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0001bc41-2e74-4d94-a61a-78b60dac0a49', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$49. óra: Síkbeli alakzatok II.$q$, $q$Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "fd3f7789-d169-441e-8308-26e073cfbce1", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "1e7b1803-9da9-448e-9445-31801845d7ce", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "de781d65-fc30-4fbf-a7cf-68b813d08712", "text": "Négyzet", "isCorrect": true}, {"id": "3020ec17-2cd5-4991-80ac-ea80b67207b4", "text": "Rombusz", "isCorrect": false}, {"id": "685cf05a-adc2-4be9-ab6a-407ea72d9898", "text": "Téglalap", "isCorrect": false}, {"id": "06718602-6cde-4e60-aed1-487c8091ae4f", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "2899415f-501a-43f9-8f06-3176c8667a77", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "f312b30a-7e88-45bb-a4dc-6c44bf002974", "text": "Rombusz", "isCorrect": true}, {"id": "f24882be-3de2-4aaa-b899-4c1849fc1477", "text": "Téglalap", "isCorrect": false}, {"id": "d195700c-e55f-45bf-873a-b763b20159f9", "text": "Trapéz", "isCorrect": false}, {"id": "bd726dbd-5792-4a86-bb52-4a4f75a83364", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "505e8e7a-6565-456c-9a17-213ca4705df0", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "e55f971b-09fe-48f1-81ed-0ebf856e1205", "text": "Igaz", "isCorrect": true}, {"id": "dc5d6ba4-abc4-4529-9fe1-297699c49dbc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f634930-9109-4086-9ef3-e1e62ec299d3", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "4d67fd64-98b5-40bb-9954-4389e1abc77e", "text": "Igaz", "isCorrect": true}, {"id": "5f8d5395-2033-428a-b639-f8e04cb191b7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c294a42-09bc-4809-8cb7-ee6fc9595d01", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "f154ce73-f695-47e0-bf98-0f9e4591104e", "text": "Igaz", "isCorrect": true}, {"id": "c7ff54b4-ebdd-4563-9461-a027ae407288", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2144d209-09bb-42ff-882f-b927d48635ef", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a32cc21d-9bde-4095-b080-0771fb618088', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$50. óra: Egybevágóság$q$, $q$Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "c5806a6f-dab5-4993-ab96-3e11943ac1ee", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "4915c558-5cb3-4892-a1ea-96e11509be77", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "d43524c6-0832-4090-afbf-863516eca84e", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "09fb363b-9a5b-4ab6-97a5-394a4a585402", "text": "Ha a területük 0", "isCorrect": false}, {"id": "f60eadeb-9e60-4755-ba70-47ff09155f13", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "64cd9090-3bfc-456e-a9a8-c80c61828762", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "195bf560-f3b3-41d5-b78f-fe2b972cfa6d", "text": "Igaz", "isCorrect": true}, {"id": "9a141e98-595e-459a-8786-0011638ad863", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8fbc650a-f483-4160-a685-96ec22a8f490", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "55e36002-7198-49f5-ad1f-9338d60541b0", "text": "Igaz", "isCorrect": true}, {"id": "84c0765c-84df-470a-a6f7-1259687cc6fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "681f9c31-9b07-4614-90f8-2a1fc8665793", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "09182e2e-52d7-446c-abe8-a24e743af84b", "text": "Igaz", "isCorrect": false}, {"id": "7dea95dc-4263-4bbd-9836-4ba75e843084", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "b9cd6b11-73b4-4601-8024-495176880ea0", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "775d950a-0569-4bb1-a4e6-4641478e436a", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "637e8990-d3fa-4e8d-a57f-43925a2a68f9", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "d8c87130-3d09-43ab-a167-05d8ee6bfd86", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "403bbc29-6fae-4c45-89df-49a839c47b95", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "cd9344c2-dcc1-4aaa-b45c-1014eea42a65", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "572062bc-1540-42f7-9f07-7470c7a45a36", "text": "Igaz", "isCorrect": false}, {"id": "c59d8d1e-c2d6-43cd-bd2d-ea93b3834218", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "433f87a4-5db9-4ad2-81cd-43ee60fc234a", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "1d8be084-9c4b-432e-9617-e74e9a8d23e3", "text": "Igaz", "isCorrect": true}, {"id": "aeb880c4-a3d7-4bee-b3b7-046ae2d3b042", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;